// Mutex & Lock Guard (C++ Standard Library)
std::mutex mtx;
int shared_resource = 0;

void access_resource() {
    // RAII principle: lock acquired on creation, released on scope exit
    std::lock_guard<std::mutex> lock(mtx);
    // Critical Section
    shared_resource++;
}


// Atomic Operations (Lock-Free Programming)
std::atomic<long> safe_counter(0);
std::atomic_bool running(true);

void worker_loop() {
    long expected = safe_counter.load();
    long desired = expected + 1;

    // Compare-and-Swap (CAS) loop
    while (!safe_counter.compare_exchange_weak(expected, desired)) {
        desired = expected + 1;
    }
}


// Condition Variables (Waiting and Signaling)
std::mutex mtx;
std::condition_variable cv;
std::queue<int> task_queue;

void waiting_thread() {
    std::unique_lock<std::mutex> lock(mtx);
    // Wait until queue is not empty (spurious wakeups handled by predicate)
    cv.wait(lock, []{ return !task_queue.empty(); });
    int task = task_queue.front();
    task_queue.pop();
}

void notifying_thread(int data) {
    {
        std::lock_guard<std::mutex> lock(mtx);
        task_queue.push(data);
    } // Mutex unlocked
    cv.notify_one();
}
